import base64, json, struct, sys

def ktest(objects, args=()):
    out = [b'KTEST', struct.pack('>I', 3), struct.pack('>I', len(args))]
    for a in args:
        out.append(struct.pack('>I', len(a)) + a)
    out.append(struct.pack('>II', 0, 0))
    out.append(struct.pack('>I', len(objects)))
    for name, data in objects:
        nb = name.encode()
        out.append(struct.pack('>I', len(nb)) + nb)
        out.append(struct.pack('>I', len(data)) + data)
    return base64.b64encode(b''.join(out)).decode()

def raw_ktest(objects, args=()):
    return ktest(objects, args)

def enc(value, width):
    return value.to_bytes(width, 'little')
PYEOF
